/**
 * Table.Cell: a data cell, a `<td>`.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/table.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import { claimSlot, scope, type Defaults } from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/table.module.css'

export interface TableCellProps {
  children?: JSX.Element
  numeric?: boolean
}

/** Table.Cell: a data cell, a `<td>`. */
export default function TableCell(given: TableCellProps): JSX.Element {
  const props = mergeProps(
    { numeric: false } as Defaults<TableCellProps, 'numeric'>,
    claimSlot(given),
  )
  return scope(() => {
    return (
      <td class={styles.cell} data-numeric={props.numeric ? '' : undefined}>
        {props.children}
      </td>
    )
  })
}
